"use client";

import { useState } from "react";

export default function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
  const [message, setMessage] = useState("");

  const validateEmail = (value: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) {
      setStatus("error");
      setMessage("Please enter your email address.");
      return;
    }
    if (!validateEmail(email)) {
      setStatus("error");
      setMessage("Please enter a valid email address.");
      return;
    }
    setStatus("success");
    setMessage("You're in! Thanks for subscribing.");
    setEmail("");
  };

  return (
    <section className="bg-[#1a1a1a] py-16">
      <div className="max-w-2xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <h2 className="text-3xl sm:text-4xl font-bold uppercase tracking-tight mb-4" style={{ fontFamily: 'Oswald, sans-serif' }}>
          Newsletter Form Signup
        </h2>
        <p className="text-white/60 mb-8">
          Stay in the know. Get workout tips, class updates, and exclusive offers delivered to your inbox.
        </p>

        <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row gap-3 max-w-md mx-auto">
          <input
            type="email"
            value={email}
            onChange={(e) => {
              setEmail(e.target.value);
              if (status !== "idle") {
                setStatus("idle");
                setMessage("");
              }
            }}
            placeholder="Enter your email"
            className="flex-1 px-4 py-3 bg-[#141414] border border-white/20 rounded text-white placeholder-white/40 focus:border-[#FF0000] focus:outline-none transition-colors"
          />
          <button
            type="submit"
            className="px-6 py-3 bg-[#FF0000] text-white font-semibold rounded hover:bg-red-700 transition-colors uppercase tracking-wide text-sm"
          >
            Subscribe
          </button>
        </form>

        {status !== "idle" && (
          <p className={`mt-4 text-sm ${status === "success" ? "text-green-400" : "text-[#FF0000]"}`}>
            {message}
          </p>
        )}
      </div>
    </section>
  );
}

