          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,0,0,0.12)_0%,_transparent_70%)]" />
          <div className="relative z-10 text-center px-4 max-w-4xl mx-auto">
            <h1 className="text-5xl sm:text-7xl font-bold uppercase tracking-tight mb-6" style={{ fontFamily: 'Oswald, sans-serif' }}>
              RedRoom RIDE FAQ
            </h1>
            <p className="text-lg sm:text-xl text-white/80 max-w-2xl mx-auto">
              Everything you need to know about our signature cycling and strength experience.
            </p>
          </div>
        </section>

        {/* FAQ Accordion */}
        <section className="py-20 px-4">
          <div className="max-w-3xl mx-auto">
            <h2 className="text-3xl sm:text-4xl font-bold uppercase tracking-tight text-center mb-12" style={{ fontFamily: 'Oswald, sans-serif' }}>
              Frequently Asked Questions
            </h2>
            <div className="space-y-4">
              {faqData.map((faq, idx) => (
                <div
                  key={idx}
                  className="bg-[#1a1a1a] border border-white/10 rounded-lg overflow-hidden"
                >
                  <button
                    onClick={() => toggleAccordion(idx)}
                    className="w-full flex items-center justify-between px-6 py-5 text-left hover:bg-[#222] transition-colors"
                  >
                    <span className="text-lg font-semibold pr-4">{faq.question}</span>
                    <RiArrowDownSLine
                      size={24}
                      className={`flex-shrink-0 text-[#FF0000] transition-transform duration-300 ${
                        openIndex === idx ? "rotate-180" : ""
                      }`}
                    />
                  </button>
                  <div
                    className={`accordion-content ${openIndex === idx ? "open" : ""}`}
                  >
                    <div className="px-6 pb-5 text-white/70 leading-relaxed">
                      {faq.answer}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>

        <Newsletter />
      </main>

      <Footer />
    </div>
  );
